import {Stack} from '@primer/react'
import {clsx} from 'clsx'
import styles from './CopilotUsageSummaryItem.module.css'

export interface CopilotUsageSummaryItemProps {
  sku: string
  consumedLicenses: number
}

export function CopilotUsageSummaryItem({sku, consumedLicenses}: CopilotUsageSummaryItemProps) {
  const capitalizedName = sku.charAt(0).toUpperCase() + sku.slice(1)

  return (
    <Stack
      direction="vertical"
      padding="none"
      gap="none"
      className={clsx(styles.fillWidth, 'gap-1')}
      data-testid="usage-summary-item"
    >
      <Stack.Item grow>
        <div className="f3 text-normal" data-testid="summary-item-amount">
          {consumedLicenses.toLocaleString()}
        </div>
      </Stack.Item>
      <Stack.Item>
        <div className={`f6 color-fg-muted ${clsx(styles.itemLineHeight)}`} data-testid="summary-amount-desc">
          {capitalizedName} licenses
        </div>
      </Stack.Item>
    </Stack>
  )
}

try{ CopilotUsageSummaryItem.displayName ||= 'CopilotUsageSummaryItem' } catch {}