import {Stack, Button} from '@primer/react'
import {PaymentSummary} from './PaymentSummary'
import type {Sku} from '../copilot-types'
import {useNavigation} from '../contexts/NavigationContext'

export interface CopilotPaymentSummaryProps {
  isTrial?: boolean
  billingTermEndDate: string
  totalCost: number
  skus: Sku[]
  headingLevel?: 'h2' | 'h3'
}

const capitalizeName = (sku: string) => sku.charAt(0).toUpperCase() + sku.slice(1)
const dollarAmount = (amount: number) => {
  return amount.toLocaleString('en-US', {minimumFractionDigits: 2})
}

export function CopilotPaymentSummary({
  billingTermEndDate,
  totalCost,
  skus,
  headingLevel,
  isTrial,
}: CopilotPaymentSummaryProps) {
  const {basePath} = useNavigation()
  // period=3 is for the current billing term
  // group=2 is for Copilot
  // query=product:copilot is for the Copilot product
  const billingDetailsHref = `${basePath}/billing/usage?period=3&group=2&query=product:copilot`
  const skuTotal = (sku: Sku) => sku.billableLicenses * sku.unitPrice
  const skuTotalFormatted = (sku: Sku) => dollarAmount(skuTotal(sku))
  const currentPayment = `$${dollarAmount(totalCost)}`
  const paymentSummaryDescription = () => {
    return `Amount based on ${skus
      .reduce((acc, sku) => acc + sku.billableLicenses, 0)
      .toLocaleString()} billable licenses${isTrial ? '' : `, due by ${billingTermEndDate}`}.`
  }

  return (
    <PaymentSummary
      title="Estimated monthly payment"
      currentPayment={currentPayment}
      description={paymentSummaryDescription()}
      headingAs={headingLevel}
      moreDetailsBody={
        <>
          <div className="f2 text-normal lh-default" data-testid="current-payment">
            {currentPayment}
          </div>
          <div className="text-normal f5 lh-default color-fg-muted my-2" data-testid="payment-description">
            {paymentSummaryDescription()}
          </div>
          {skus.map(sku => (
            <Stack direction="vertical" className="border-top py-2" key={sku.sku}>
              <Stack direction="horizontal" gap="condensed" className="width-full">
                <Stack direction="vertical" className="width-full">
                  <span className="text-normal f5 lh-default" data-testid={`${sku.sku}-billable-licenses`}>
                    {sku.billableLicenses} Copilot {capitalizeName(sku.sku)} licenses
                  </span>
                  <span className="text-normal f5 lh-default color-fg-muted" data-testid={`${sku.sku}-unit-price`}>
                    ${dollarAmount(sku.unitPrice)}/month each
                  </span>
                </Stack>
                <span className="text-bold f5 lh-default" data-testid={`${sku.sku}-billable-amount`}>
                  ${skuTotalFormatted(sku)}
                </span>
              </Stack>
            </Stack>
          ))}
        </>
      }
      moreDetailsButtons={
        <Button as="a" href={billingDetailsHref} data-testid="view-usage-details-btn">
          View billing details
        </Button>
      }
    />
  )
}

try{ CopilotPaymentSummary.displayName ||= 'CopilotPaymentSummary' } catch {}